#include <stdio.h>
#include <stdlib.h>
int main(void) { int n; long long x; if(scanf("%d %lld", &n, &x)!=2) return 1;
int size=1048576; int *a=(int*)malloc(sizeof(int)*size); if(!a) return 2;
for(int i=0;i<size;i++) a[i]=2*i; x&=size-1; for(int i=0;i<n;i++) { int target=(int)(2*x), lo=0,hi=size; while(lo<hi){int mid=(lo+hi)/2; if(a[mid]<target)lo=mid+1;else hi=mid;} x=(((long long)lo)*1664525+1013904223)&(size-1); }
printf("%lld\n", x); return 0; }

